// CI restores GOMODCACHE below the checkout (.artifacts/cache/go-mod). Generate
// real profiles in that layout, with a local replacement and a generated file, and
// require the -coverpkg scope to instrument exactly the modules being accounted.
func TestGeneratedProfileWithModuleCacheInCheckout(t *testing.T) {
	root := generationFixture(t)
	env := generationEnv(t, root)
	mapping := []string{"-module", "example.test/fork=third_party/fork"}
	var scope, out, diagnostics bytes.Buffer
	requireCoverageNoError(
		t,
		run(append([]string{"-repo", root, "-print-coverpkg"}, mapping...), &scope, &diagnostics),
	)
	if scope.String() != "example.test/repo/...,example.test/fork/...\n" {
		t.Fatalf("coverpkg scope: %q", &scope)
	}

	// Precondition: a relative pattern selects packages by directory, so it also
	// instruments the cached dependency, and the reporter rejects those records.
	relative := goTestProfile(t, root, env, "./...")
	if _, err := os.Stat(filepath.Join(root, ".artifacts/cache/go-mod/example.test/dep@v1.0.0/dep.go")); err != nil {
		t.Fatalf("fixture module cache is not inside the checkout: %v", err)
	}
	err := run(append([]string{"-repo", root, "-profile", relative}, mapping...), &out, &diagnostics)
	if err == nil || err.Error() != `profile path outside module: "example.test/dep/dep.go"` || out.Len() != 0 {
		t.Fatalf("relative scope no longer instruments the in-checkout module cache: err=%v report=%s", err, &out)
	}

	scoped := goTestProfile(t, root, env, strings.TrimSpace(scope.String()))
	requireCoverageNoError(t, run(append([]string{"-repo", root, "-profile", scoped}, mapping...), &out, &diagnostics))
	checkGeneratedReport(t, out.Bytes())
}

func generationFixture(t *testing.T) string {
	t.Helper()
	root := t.TempDir()
	write(t, root, "go.mod", "module example.test/repo\n\ngo 1.27\n\n"+
		"require (\n\texample.test/dep v1.0.0\n\texample.test/fork v0.0.0\n)\n\n"+
		"replace example.test/fork => ./third_party/fork\n")
	write(t, root, "pkg/pkg.go", "package pkg\n\nimport (\n\t\"example.test/dep\"\n\t\"example.test/fork\"\n)\n\n"+
		"func Sum(n int) int { return dep.Double(n) + fork.Triple(n) + generated() }\n")
	write(t, root, "pkg/gen.go", "// Code generated by fixture. DO NOT EDIT.\n\npackage pkg\n\n"+
		"func generated() int { return 1 }\n")
	write(t, root, "pkg/pkg_test.go", "package pkg\n\nimport \"testing\"\n\n"+
		"func TestSum(t *testing.T) {\n\tif got := Sum(1); got != 6 {\n\t\tt.Fatal(got)\n\t}\n}\n")
	write(t, root, "third_party/fork/go.mod", "module example.test/fork\n\ngo 1.27\n")
	write(t, root, "third_party/fork/fork.go", "package fork\n\nfunc Triple(n int) int { return 3 * n }\n")
	return root
}

// generationEnv isolates module resolution: a file proxy outside the checkout
// serves the only downloaded dependency into a module cache below the root.
func generationEnv(t *testing.T, root string) []string {
	t.Helper()
	proxy := t.TempDir()
	const mod = "module example.test/dep\n\ngo 1.27\n"
	write(t, proxy, "example.test/dep/@v/v1.0.0.info", `{"Version":"v1.0.0"}`)
	write(t, proxy, "example.test/dep/@v/v1.0.0.mod", mod)
	var archive bytes.Buffer
	files := zip.NewWriter(&archive)
	for name, data := range map[string]string{
		"go.mod": mod,
		"dep.go": "package dep\n\nfunc Double(n int) int { return 2 * n }\n",
	} {
		file, err := files.Create("example.test/dep@v1.0.0/" + name)
		requireCoverageNoError(t, err)
		_, err = io.WriteString(file, data)
		requireCoverageNoError(t, err)
	}
	requireCoverageNoError(t, files.Close())
	write(t, proxy, "example.test/dep/@v/v1.0.0.zip", archive.String())
	// -modcacherw lets TempDir cleanup remove the extracted module.
	return append(os.Environ(),
		"GOENV=off", "GOWORK=off", "GOTOOLCHAIN=local", "GOFLAGS=-mod=mod -modcacherw", "GOCOVERDIR=",
		"GOMODCACHE="+filepath.Join(root, ".artifacts/cache/go-mod"), "GOPROXY=file://"+filepath.ToSlash(proxy),
		"GOSUMDB=off", "GOPRIVATE=", "GONOPROXY=", "GONOSUMDB=", "GOINSECURE=",
	)
}

func goTestProfile(t *testing.T, root string, env []string, coverpkg string) string {
	t.Helper()
	goBinary, err := exec.LookPath("go")
	if err != nil {
		t.Fatalf("go is required to generate a real coverage profile: %v", err)
	}
	profile := filepath.Join(t.TempDir(), "root.out")
	budget := childBudget(t, time.Minute)
	ctx, cancel := context.WithTimeout(t.Context(), budget)
	defer cancel()
	// The context bounds compilation too; -timeout also stops the fixture test
	// binary on its own if this process dies before it can kill the group.
	// Owner: FRY maintainers; review by 2027-01-18.
	// #nosec G204 -- go is resolved by LookPath; fixed test arguments run in a temporary fixture, with no shell.
	command := exec.CommandContext(
		ctx, goBinary, "test", "-count=1", "-timeout="+budget.String(), "-covermode=atomic",
		"-coverpkg="+coverpkg, "-coverprofile="+profile, "./...",
	)
	command.Dir = root
	command.Env = env
	if output, err := outputInGroup(t, command, childWaitDelay); err != nil {
		t.Fatalf("go test -coverpkg=%s: %v (deadline: %v)\n%s", coverpkg, err, ctx.Err(), output)
	}
	return profile
}

// childWaitDelay bounds how long Wait drains output after the command exits or
// is canceled while another process still holds the pipe.
const childWaitDelay = 5 * time.Second

// childBudget caps a child below the parent's -timeout, leaving time to cancel,
// drain and report before the test binary's own timeout panic.
func childBudget(t *testing.T, limit time.Duration) time.Duration {
	t.Helper()
	if deadline, ok := t.Deadline(); ok {
		limit = min(limit, time.Until(deadline)-2*childWaitDelay)
	}
	if limit <= 0 {
		t.Fatal("no test time remains for a child process")
	}
	return limit
}

// outputInGroup runs command in a new process group and returns its combined
// output. It kills the whole group when the command's context ends and again
// after the command returns: Wait can reap the command before the context
// watcher runs, and a command that exits first can leave descendants running
// after WaitDelay closes their pipe. An anchor process leads the group and is
// reaped only after the final kill, so the group ID cannot be reused while it is
// signaled, even when the command and its descendants are gone.
func outputInGroup(t *testing.T, command *exec.Cmd, waitDelay time.Duration) ([]byte, error) {
	t.Helper()
	lifetime := time.Hour
	if deadline, ok := t.Deadline(); ok {
		lifetime = time.Until(deadline)
	}
	// The anchor also stops by itself if this process dies before cleanup.
	// Owner: FRY maintainers; review by 2027-01-18.
	// #nosec G204 -- fixed sleep command; only its duration is computed.
	anchor := exec.CommandContext(t.Context(), "sleep", strconv.FormatInt(int64(lifetime/time.Second)+1, 10))
	anchor.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
	if err := anchor.Start(); err != nil {
		t.Fatalf("start process group anchor: %v", err)
	}
	group := anchor.Process.Pid
	defer func() {
		if err := syscall.Kill(-group, syscall.SIGKILL); err != nil {
			t.Errorf("kill process group %d: %v", group, err)
		}
		if err := anchor.Wait(); err != nil && !killedBySIGKILL(err) {
			t.Errorf("reap process group anchor: %v", err)
		}
	}()
	command.SysProcAttr = &syscall.SysProcAttr{Setpgid: true, Pgid: group}
	command.Cancel = func() error { return syscall.Kill(-group, syscall.SIGKILL) }
	command.WaitDelay = waitDelay
	return command.CombinedOutput()
}

func killedBySIGKILL(err error) bool {
	var exit *exec.ExitError
	if !errors.As(err, &exit) {
		return false
	}
	status, ok := exit.Sys().(syscall.WaitStatus)
	return ok && status.Signaled() && status.Signal() == syscall.SIGKILL
}

func TestOutputInGroupStopsDescendants(t *testing.T) {
	t.Run("leader running at deadline", func(t *testing.T) {
		ctx, cancel := context.WithTimeout(t.Context(), childBudget(t, 100*time.Millisecond))
		defer cancel()
		// The background sleep inherits the output pipe. Killing only the shell
		// would leave the output open until WaitDelay.
		start := time.Now()
		_, err := outputInGroup(t, exec.CommandContext(ctx, "sh", "-c", "sleep 30 & wait"), childWaitDelay)
		if elapsed := time.Since(start); !killedBySIGKILL(err) ||
			!errors.Is(ctx.Err(), context.DeadlineExceeded) || elapsed >= childWaitDelay {
			t.Fatalf("descendant outlived cancellation: err=%v elapsed=%v", err, elapsed)
		}
	})
	t.Run("leader exits first", func(t *testing.T) {
		// Wait reaps the shell without cancellation; WaitDelay closes the pipe the
		// background sleep still holds, and only the final group kill stops it.
		ctx, cancel := context.WithTimeout(t.Context(), childBudget(t, 5*time.Second))
		defer cancel()
		command := exec.CommandContext(ctx, "sh", "-c", "sleep 30 & echo $!")
		output, err := outputInGroup(t, command, 100*time.Millisecond)
		if !errors.Is(err, exec.ErrWaitDelay) {
			t.Fatalf("descendant did not hold the output after the shell exited: err=%v", err)
		}
		pid, err := strconv.Atoi(strings.TrimSpace(string(output)))
		requireCoverageNoError(t, err)
		for deadline := time.Now().Add(time.Second); running(t, pid); {
			if time.Now().After(deadline) {
				t.Fatalf("descendant %d survived process group cleanup", pid)
			}
			time.Sleep(10 * time.Millisecond)
		}
	})
}

// running reports whether pid can still execute. A zombie has already stopped;
// its new parent may not have reaped it yet. No signal is sent using this PID.
func running(t *testing.T, pid int) bool {
	t.Helper()
	stat, err := os.ReadFile("/proc/" + strconv.Itoa(pid) + "/stat")
	if errors.Is(err, os.ErrNotExist) || errors.Is(err, syscall.ESRCH) {
		return false
	}
	requireCoverageNoError(t, err)
	// The command name is parenthesized and may itself contain spaces or ')'.
	end := strings.LastIndex(string(stat), ") ")
	if end < 0 || end+2 >= len(stat) {
		t.Fatalf("invalid process state for %d: %q", pid, stat)
	}
	return stat[end+2] != 'Z' && stat[end+2] != 'X'
}

func checkGeneratedReport(t *testing.T, raw []byte) {
	t.Helper()
	var got report
	requireCoverageNoError(t, json.Unmarshal(raw, &got))
	if got.Module != "example.test/repo" || len(got.Packages) != 1 || got.Packages[0] != (packageReport{
		Package:     "example.test/repo/pkg",
		Handwritten: counts{1, 1},
		Generated:   counts{1, 1},
		Unfiltered:  counts{2, 2},
	}) {
		t.Fatalf("root scope: %+v", got)
	}
	if len(got.Dependencies) != 1 || got.Dependencies[0].Module != "example.test/fork" ||
		len(got.Dependencies[0].Packages) != 1 || got.Dependencies[0].Packages[0] != (packageReport{
		Package:     "example.test/fork",
		Handwritten: counts{1, 1},
		Unfiltered:  counts{1, 1},
	}) {
		t.Fatalf("local replacement scope: %+v", got.Dependencies)
	}
}
